// Grimbound wiki viewer. Data: data/wiki.js (window.AURELITH_WIKI), generated by tools/wiki/export_wiki.gd.
// Routes (hash):  #/  ·  #/c/<category>  ·  #/e/<category>/<id>  ·  #/s/<search words>
(function () {
  "use strict";
  const W = window.AURELITH_WIKI;
  const main = document.getElementById("wiki-main");
  const catsEl = document.getElementById("wiki-cats");
  const search = document.getElementById("wiki-search");
  const spoilerBox = document.getElementById("spoiler-toggle");
  if (!W || !main) { if (main) main.innerHTML = '<p class="empty">The wiki data is missing. Run tools/wiki/export_wiki.gd.</p>'; return; }

  const byKey = {};
  W.entries.forEach((e) => { byKey[e.key] = e; e._text = (e.name + " " + e.summary + " " + e.fields.map((f) => f.join(" ")).join(" ")).toLowerCase(); });
  const catName = {};
  W.categories.forEach((c) => { catName[c.id] = c.name; });
  const CAT_BLURB = {
    weapons: "Every weapon type, its damage by rarity, and where to find or forge it.",
    armour: "Armour pieces from loot and the forge.", trinkets: "Charms, lockets and bookmarks.",
    materials: "What drops, what grows, what it is for.", consumables: "Potions, elixirs, bombs and party meals.",
    runes: "Element runes for your gear's sockets.", scrolls: "Rare recipes found in dungeons.",
    stations: "Shops, crafting stations and services in the Royal Capital.", gathering: "Personal gathering nodes in mission maps.",
    spells: "The seven grimoires and their spell trees.", builds: "Fifteen playstyle archetypes, one weapon each: gear, spells, tree points and where to get every piece.",
    named_weapons: "Lore-named weapons with a signature perk, from specific bosses or crafted from rare drops.",
    relics: "One build-defining key item per archetype for the Relic slot.",
    sets: "Named six-piece sets for every archetype, with where each piece drops.", enemies: "Who you fight, what they hit with, what they drop.",
    bosses: "Phases, attacks and rewards.", missions: "Dungeons, hunts, boss fights and story missions.",
    regions: "The places of Aurelith.", crew: "Who flies with you.", loot: "Exact drop tables.", guides: "How the systems work.",
    familiars: "The seven familiars: how they grow from Born to Unison, their X attack, special and tree.",
    weapon_mastery: "One mastery tree per weapon: skill rank-ups, modifiers, alternate skills and passives.",
    role_trees: "Tank, Damage and Healer trees for all seven grimoires, every node tagged by type.",
  };

  let spoilers = false;
  try { spoilers = localStorage.getItem("aurelith.wiki.spoilers") === "1"; } catch (e) { /* storage blocked */ }
  spoilerBox.checked = spoilers;
  spoilerBox.addEventListener("change", () => {
    spoilers = spoilerBox.checked;
    try { localStorage.setItem("aurelith.wiki.spoilers", spoilers ? "1" : "0"); } catch (e) { /* ignore */ }
    route();
  });

  const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const visible = (e) => e && (spoilers || !e.spoiler);
  const rcls = (r) => (r >= 0 && r <= 4 ? ` r${r}` : "");
  const href = (key) => "#/e/" + key;

  function link(text, ref, r) {
    const target = ref && byKey[ref];
    if (!target) return `<span class="${rcls(r ?? -1).trim()}">${esc(text)}</span>`;
    if (!visible(target)) return `<span title="Story spoiler">${esc(text)}</span>`;
    const rr = r ?? target.rarity;
    return `<a href="${href(ref)}" class="${rcls(rr).trim()}">${esc(text)}</a>`;
  }
  function cell(c) {
    if (Array.isArray(c)) return c.map((x) => cell(x)).join("");
    if (c && typeof c === "object") return link(c.t, c.ref, c.r);
    return esc(c);
  }
  const hiddenBox = (what) => `<div class="spoiler-box">${what} hidden: story spoiler. <a href="#" data-reveal>Show spoilers</a></div>`;

  // ---------------------------------------------------------------- sidebar
  function renderCats(active) {
    const counts = {};
    W.entries.forEach((e) => { if (visible(e)) counts[e.cat] = (counts[e.cat] || 0) + 1; });
    catsEl.innerHTML = (W.planner && W.planner.elements ? `<li><a href="#/planner" class="${active === "planner" ? "on" : ""}"><b>Build planner</b><span class="n">new</span></a></li>` : "") + W.categories.map((c) => `<li><a href="#/c/${c.id}" class="${c.id === active ? "on" : ""}">${esc(c.name)}<span class="n">${counts[c.id] || 0}</span></a></li>`).join("");
  }
  const catBox = document.getElementById("cats-box");
  if (catBox && window.matchMedia("(max-width: 900px)").matches) catBox.open = false;
  catsEl.addEventListener("click", (ev) => { if (catBox && ev.target.closest("a") && window.matchMedia("(max-width: 900px)").matches) catBox.open = false; });
  document.getElementById("wiki-gen").textContent = "Generated from the game data, " + (W.generated || "");

  // ---------------------------------------------------------------- views
  function card(e) {
    return `<a class="wiki-card" href="${href(e.key)}"><b class="${rcls(e.rarity).trim()}">${esc(e.name)}</b><span>${esc(e.summary)}</span></a>`;
  }
  function viewHome() {
    renderCats("");
    const feat = W.planner && W.planner.elements ? `<a class="wiki-card feature-card" href="#/planner"><b>Build planner</b><span>Pick a grimoire, a weapon and a role, spend your tree points and share the link.</span></a>` : "";
    main.innerHTML = `<section class="wiki-list"><h2>Browse the codex</h2><div class="wiki-cards">${feat}${W.categories.map((c) => {
      const n = W.entries.filter((e) => e.cat === c.id && visible(e)).length;
      return `<a class="wiki-card" href="#/c/${c.id}"><b>${esc(c.name)}</b><span>${n} pages · ${esc(CAT_BLURB[c.id] || "")}</span></a>`;
    }).join("")}</div></section>`;
  }
  function viewCat(cat) {
    renderCats(cat);
    const list = W.entries.filter((e) => e.cat === cat);
    const shown = list.filter(visible);
    const hidden = list.length - shown.length;
    main.innerHTML = `<section class="wiki-list"><p class="crumbs"><a href="#/">Wiki</a> › ${esc(catName[cat] || cat)}</p><h2>${esc(catName[cat] || cat)}</h2>
      <p>${esc(CAT_BLURB[cat] || "")}</p>
      <div class="wiki-cards">${shown.map(card).join("") || '<p class="empty">Nothing here yet.</p>'}</div>
      ${hidden ? `<p style="margin-top:16px">${hiddenBox(hidden + (hidden === 1 ? " page" : " pages"))}</p>` : ""}</section>`;
  }
  function viewSearch(q) {
    renderCats("");
    const words = q.toLowerCase().split(/\s+/).filter(Boolean);
    const hits = W.entries.filter((e) => visible(e) && words.every((w) => e._text.includes(w)))
      .map((e) => [e, e.name.toLowerCase().startsWith(words[0] || "") ? 0 : e.name.toLowerCase().includes(words[0] || "") ? 1 : 2])
      .sort((a, b) => a[1] - b[1] || a[0].name.localeCompare(b[0].name)).map((x) => x[0]);
    main.innerHTML = `<section class="wiki-list"><p class="crumbs"><a href="#/">Wiki</a> › Search</p><h2>${hits.length} result${hits.length === 1 ? "" : "s"} for “${esc(q)}”</h2>
      <div class="wiki-cards">${hits.slice(0, 120).map((e) => card(e).replace("</b>", `</b><i class="tagchip">${esc(catName[e.cat])}</i>`)).join("") || '<p class="empty">No pages match. Try fewer words.</p>'}</div></section>`;
  }
  function viewEntry(key) {
    const e = byKey[key];
    if (!e) { main.innerHTML = '<p class="empty">No such page. <a href="#/">Back to the wiki</a></p>'; return; }
    renderCats(e.cat);
    let html = `<article class="wiki-entry"><p class="crumbs"><a href="#/">Wiki</a> › <a href="#/c/${e.cat}">${esc(catName[e.cat])}</a></p>`;
    html += `<h1 class="${rcls(e.rarity).trim()}">${esc(e.name)}</h1>`;
    const chips = [...(e.spoiler ? ["Spoiler"] : []), ...e.tags];
    if (chips.length) html += `<p>${chips.map((t) => `<span class="tagchip">${esc(t)}</span>`).join("")}</p>`;
    if (e.spoiler && !spoilers) {
      html += hiddenBox("This page is") + "</article>";
      main.innerHTML = html;
      return;
    }
    if (e.summary) html += `<p class="summary">${esc(e.summary)}</p>`;
    if (e.picks && e.picks.length) html += `<p class="pick-row">${e.picks.map((pk, i) => `<a class="btn ${i ? "btn-ghost" : "btn-primary"}" href="#/planner/${esc(pk.code)}">Plan it: ${esc(pk.t)}</a>`).join(" ")}</p>`;
    else if (e.planner) html += `<p><a class="btn btn-primary" href="#/planner/${esc(e.planner)}">Open in the build planner</a></p>`;
    if (e.img) html += `<img class="entry-img" src="${esc(e.img)}" alt="${esc(e.name)} at every rarity, common to legendary" loading="lazy">`;
    if (e.fields.length) html += `<dl class="fields">${e.fields.map((f) => `<div><dt>${esc(f[0])}</dt><dd>${esc(f[1])}</dd></div>`).join("")}</dl>`;
    for (const s of e.sections) {
      html += `<section class="wsec"><h2>${esc(s.title)}</h2>`;
      if (s.spoiler && !spoilers) { html += hiddenBox("This part is") + "</section>"; continue; }
      if (s.rows) {
        const rows = s.rows.filter((r) => spoilers || (!r.s && (!r.ref || !byKey[r.ref] || visible(byKey[r.ref]))));
        const cut = s.rows.length - rows.length;
        html += rows.length ? `<ul>${rows.map((r) => `<li><span>${link(r.t, r.ref)}</span>${r.n ? `<span class="n">${esc(r.n)}</span>` : ""}</li>`).join("")}</ul>` : "";
        if (cut) html += `<p style="margin-top:8px">${hiddenBox(cut + (cut === 1 ? " line" : " lines"))}</p>`;
      } else if (s.table) {
        html += `<div class="table-wrap"><table class="wtable"><thead><tr>${s.table.head.map((h) => `<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${
          s.table.rows.map((r) => `<tr>${r.map((c) => `<td>${cell(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
      } else if (s.text) {
        html += `<p>${esc(s.text)}</p>`;
      }
      html += "</section>";
    }
    main.innerHTML = html + "</article>";
  }

  // ---------------------------------------------------------------- build planner
  // Share code: <element>.<weapon>.<role>.<level>.<offense digits>-<arts digits>-<support digits>
  // (one digit per node, in the order of W.planner.elements[el].nodes[branch]: main column, then role paths).
  const P = W.planner;
  let plan = null;
  function newPlan(el, weapon, role, level) {
    const ranks = {};
    P.branches.forEach((br) => P.elements[el].nodes[br].forEach((n) => { ranks[n.id] = 0; }));
    return { el, weapon, role, level, ranks };
  }
  function decode(code) {
    const parts = (code || "").split(".");
    const el = P.elements[parts[0]] ? parts[0] : Object.keys(P.elements)[0];
    const weapon = P.weapons.some((w) => w.id === parts[1]) ? parts[1] : P.weapons[0].id;
    const role = P.roles.some((r) => r.id === parts[2]) ? parts[2] : "dps";
    const level = Math.min(P.level_cap, Math.max(1, parseInt(parts[3], 10) || P.level_cap));
    const p = newPlan(el, weapon, role, level);
    const groups = (parts[4] || "").split("-");
    P.branches.forEach((br, bi) => {
      const digits = groups[bi] || "";
      P.elements[el].nodes[br].forEach((n, i) => { p.ranks[n.id] = Math.min(n.max, parseInt(digits[i], 10) || 0); });
    });
    return p;
  }
  function encode(p) {
    const digits = P.branches.map((br) => P.elements[p.el].nodes[br].map((n) => String(p.ranks[n.id] || 0)).join("")).join("-");
    return `${p.el}.${p.weapon}.${p.role}.${p.level}.${digits}`;
  }
  const used = (p) => Object.values(p.ranks).reduce((a, b) => a + b, 0);
  const branchSpent = (p, br, belowTier = 99) => P.elements[p.el].nodes[br].reduce((a, n) => a + (n.tier < belowTier ? p.ranks[n.id] : 0), 0);
  function valid(p) {
    if (used(p) > p.level) return "Not enough tree points at this level";
    for (const br of P.branches) {
      for (const n of P.elements[p.el].nodes[br]) {
        if (!p.ranks[n.id]) continue;
        if (n.need_level > p.level) return `${n.name} needs level ${n.need_level}`;
        if (branchSpent(p, br, n.tier) < n.need_points) return `${n.name} needs ${n.need_points} points in the lower tiers of ${P.branch_names[br]}`;
      }
    }
    return "";
  }
  function roleOf(id) { return P.roles.find((r) => r.id === id) || { name: id, path: "", blurb: "" }; }
  function bump(id, d) {
    const n = P.branches.flatMap((br) => P.elements[plan.el].nodes[br]).find((x) => x.id === id);
    if (!n) return;
    const before = plan.ranks[id];
    plan.ranks[id] = Math.max(0, Math.min(n.max, before + d));
    const err = valid(plan);
    if (err) { plan.ranks[id] = before; flash(err); return; }
    savePlan();
  }
  function flash(msg) { const el = document.getElementById("pl-msg"); if (el) { el.textContent = msg; el.classList.add("show"); } }
  function savePlan() { history.replaceState(null, "", "#/planner/" + encode(plan)); drawPlanner(); }

  function viewPlanner(code) {
    renderCats("planner");
    if (!P || !P.elements) { main.innerHTML = '<p class="empty">The planner data is missing. Run tools/wiki/export_wiki.gd.</p>'; return; }
    plan = decode(code || (W.builds && W.builds[0] ? W.builds[0].code : ""));
    if (!code) plan = newPlan(plan.el, plan.weapon, "dps", P.level_cap);
    drawPlanner();
  }
  function drawPlanner() {
    const p = plan, role = roleOf(p.role);
    const opt = (list, cur) => list.map((o) => `<option value="${esc(o.id)}"${o.id === cur ? " selected" : ""}>${esc(o.name)}</option>`).join("");
    const els = Object.keys(P.elements).map((k) => ({ id: k, name: P.elements[k].name }));
    const builds = (W.builds || []).map((b) => ({ id: b.code, name: b.name + " · " + (P.weapons.find((w) => w.id === b.weapon) || {}).name }));
    const left = p.level - used(p);
    let html = `<article class="wiki-entry planner"><p class="crumbs"><a href="#/">Wiki</a> › Build planner</p><h1>Build planner</h1>
      <p class="summary">There are no classes in Aurelith: your grimoire is your class. Pick its element, a weapon and a role, then spend one tree point per level.</p>
      <div class="pl-controls">
        <label>Grimoire<select id="pl-el">${opt(els, p.el)}</select></label>
        <label>Weapon<select id="pl-weapon">${opt(P.weapons, p.weapon)}</select></label>
        <label>Role<select id="pl-role">${opt(P.roles, p.role)}</select></label>
        <label>Level<input id="pl-level" type="number" min="1" max="${P.level_cap}" value="${p.level}"></label>
        <label class="wide">Start from a pre-made build<select id="pl-build"><option value="">Choose...</option>${opt(builds, "")}</select></label>
      </div>
      <div class="pl-bar"><b class="pl-left ${left < 0 ? "bad" : ""}">${left}</b> of ${p.level} points left
        <span class="pl-role">${esc(role.name)}: ${esc(role.blurb)}</span>
        <button class="btn btn-ghost" type="button" id="pl-reset">Reset</button>
        <button class="btn btn-primary" type="button" id="pl-copy">Copy share link</button></div>
      <p class="status warn" id="pl-msg" role="status"></p>
      <div class="pl-branches">`;
    for (const br of P.branches) {
      const nodes = P.elements[p.el].nodes[br];
      html += `<section class="pl-branch" style="--bc:${P.branch_cols[br]}"><h2>${esc(P.branch_names[br])} <span>${branchSpent(p, br)} pts</span></h2>`;
      for (let t = 0; t < P.tiers.length; t++) {
        const tn = nodes.filter((n) => n.tier === t);
        if (!tn.length) continue;
        const open = branchSpent(p, br, t) >= P.tiers[t][0] && p.level >= P.tiers[t][1];
        html += `<div class="pl-tier ${open ? "" : "locked"}"><h3>Tier ${t + 1} <span>${P.tiers[t][0]} pts in branch · level ${P.tiers[t][1]}</span></h3>`;
        for (const n of tn) {
          const k = p.ranks[n.id] || 0;
          const pathTag = n.path ? `<i class="tagchip">${esc(n.path === "healer" ? "Healer path" : "Guardian path")}</i>` : "";
          const off = n.path && roleOf(p.role).path !== n.path ? " offrole" : "";
          html += `<div class="pl-node${k ? " on" : ""}${off}" title="${esc(n.text)}">
            <div class="pl-name"><b>${esc(n.name)}</b> ${pathTag}<small>${esc(n.kind)}${n.page ? " · needs a Grimoire Page" : ""}</small><span class="pl-text">${esc(n.text)}</span></div>
            <div class="pl-ranks"><button type="button" data-n="${esc(n.id)}" data-d="-1" aria-label="Remove a point from ${esc(n.name)}">−</button>
            <span>${k}/${n.max}</span><button type="button" data-n="${esc(n.id)}" data-d="1" aria-label="Add a point to ${esc(n.name)}">+</button></div></div>`;
        }
        html += "</div>";
      }
      html += "</section>";
    }
    html += "</div>";
    // summary: role bar and learned spells
    const all = P.branches.flatMap((br) => P.elements[p.el].nodes[br]);
    const spells = all.filter((n) => n.kind === "spell" && p.ranks[n.id]);
    const bar = spells.filter((n) => n.path && n.path === role.path && n.shape !== "revive").slice(0, 3);
    const rest = spells.filter((n) => !bar.includes(n));
    html += `<section class="wsec"><h2>Your spells</h2>${spells.length ? "" : "<p>No spells learned yet: add points to a spell node.</p>"}<ul>
      ${bar.map((n) => `<li><span>Role bar: <b>${esc(n.name)}</b></span><span class="n">rank ${p.ranks[n.id]}</span></li>`).join("")}
      ${rest.map((n) => `<li><span>${esc(n.name)}</span><span class="n">rank ${p.ranks[n.id]}${n.page ? " · Grimoire Page" : ""}</span></li>`).join("")}</ul>
      <p style="margin-top:10px">Equip up to three in slots 1-3. Weapon: <a href="#/e/weapons/${esc(p.weapon)}">${esc((P.weapons.find((w) => w.id === p.weapon) || {}).name)}</a> ·
      Grimoire: <a href="#/e/spells/${esc(p.el)}">${esc(P.elements[p.el].name)}</a> (${esc(P.elements[p.el].effect)})</p></section>`;
    const match = (W.builds || []).find((b) => b.el === p.el && b.role === p.role);
    if (match) html += `<p>Gear, cloak and where to get each piece: <a href="#/e/builds/${esc(match.id)}">the ${esc(match.name)} build</a>.</p>`;
    main.innerHTML = html + "</article>";
    const re = (id, fn) => document.getElementById(id).addEventListener("change", fn);
    re("pl-el", (ev) => { plan = newPlan(ev.target.value, p.weapon, p.role, p.level); savePlan(); });
    re("pl-weapon", (ev) => { plan.weapon = ev.target.value; savePlan(); });
    re("pl-role", (ev) => { plan.role = ev.target.value; savePlan(); });
    re("pl-level", (ev) => { plan.level = Math.min(P.level_cap, Math.max(1, parseInt(ev.target.value, 10) || 1)); savePlan(); if (valid(plan)) flash(valid(plan)); });
    re("pl-build", (ev) => { if (ev.target.value) { plan = decode(ev.target.value); savePlan(); } });
    document.getElementById("pl-reset").addEventListener("click", () => { plan = newPlan(p.el, p.weapon, p.role, p.level); savePlan(); });
    document.getElementById("pl-copy").addEventListener("click", () => {
      const url = location.href;
      const done = () => flash("Link copied: " + url);
      if (navigator.clipboard) navigator.clipboard.writeText(url).then(done, () => flash(url)); else flash(url);
    });
    main.querySelectorAll(".pl-ranks button").forEach((b) => b.addEventListener("click", () => bump(b.dataset.n, parseInt(b.dataset.d, 10))));
  }


  // ---------------------------------------------------------------- routing
  function route() {
    const h = decodeURIComponent(location.hash.replace(/^#\/?/, ""));
    const [kind, ...rest] = h.split("/");
    if (kind === "planner") viewPlanner(rest.join("/"));
    else if (kind === "c" && rest[0]) viewCat(rest[0]);
    else if (kind === "e" && rest.length >= 2) viewEntry(rest[0] + "/" + rest.slice(1).join("/"));
    else if (kind === "s") viewSearch(rest.join("/"));
    else viewHome();
    if (kind !== "s") search.value = kind === "s" ? rest.join("/") : search.value;
  }
  main.addEventListener("click", (ev) => {
    const a = ev.target.closest("[data-reveal]");
    if (!a) return;
    ev.preventDefault();
    spoilerBox.checked = true;
    spoilerBox.dispatchEvent(new Event("change"));
  });
  let t = 0;
  search.addEventListener("input", () => {
    clearTimeout(t);
    t = setTimeout(() => {
      const q = search.value.trim();
      if (q) history.replaceState(null, "", "#/s/" + encodeURIComponent(q)); else history.replaceState(null, "", "#/");
      route();
    }, 120);
  });
  window.addEventListener("hashchange", () => { route(); if (!location.hash.startsWith("#/s/")) window.scrollTo({ top: 0 }); });
  route();
})();
